      targets = { node: nodeVersion };
      needsPolyfillsForOldNode = true;
      break;
    case "test":
      targets = { node: "current" };
      needsPolyfillsForOldNode = true;
      dynamicESLintVersionCheck = true;
      break;
    case "development":
      envOpts.debug = true;
      targets = { node: "current" };
      dynamicESLintVersionCheck = true;
      break;
